I have this Toast component in my Next.js app and toasts feel slow and janky when several stack up at once. Can you review it?

```tsx
import { motion } from "framer-motion";
import { useEffect, useState } from "react";

export function Toast({ message, onDismiss }: { message: string; onDismiss: () => void }) {
  const [mounted, setMounted] = useState(false);

  useEffect(() => {
    setMounted(true);
    const timer = setTimeout(onDismiss, 3000);
    return () => clearTimeout(timer);
  }, [onDismiss]);

  return (
    <motion.div
      initial={{ scale: 0, opacity: 0 }}
      animate={{ scale: 1, opacity: 1 }}
      exit={{ scale: 0, opacity: 0 }}
      transition={{ duration: 0.5, ease: "easeIn" }}
      style={{ transition: "all 500ms", background: "white", padding: "16px", borderRadius: "8px" }}
    >
      {message}
    </motion.div>
  );
}
```

For context the rest of the app is React + Tailwind v4. What would you change?
